/** Finance evidence only: availability never establishes that money was received/refunded. */
@RestController
public final class FinanceVouchers {
 @FunctionalInterface interface Identity {Map<String,Object> read(String token,String csrf,boolean write,String purpose,HttpServletRequest r);}
 final Tickets t;final Path root;final Identity identity;
 @org.springframework.beans.factory.annotation.Autowired
 public FinanceVouchers(Tickets t){this(t,FileStore.ROOT,(token,csrf,write,purpose,r)->{var b=new LinkedHashMap<String,Object>();b.put("sessionToken",token);b.put("purpose",write?"MONEY_WRITE":"MONEY_READ");if(write)b.put("csrfToken",csrf);var f=Chain.call("ticket-identity","/internal/identity/domain-authorizations",b,Chain.trace(r),Chain.deadline(r));Chain.fresh(f,Chain.deadline(r));return f;});}
 FinanceVouchers(Tickets t,Path root,Identity identity){this.t=t;this.root=root.toAbsolutePath().normalize();this.identity=identity;try{if(Files.isSymbolicLink(this.root)||!this.root.toRealPath().equals(this.root))throw new IOException();}catch(IOException e){throw new IllegalStateException("Private voucher directory unavailable");}}
 record Actor(long tenant,long user,long company,String token,String csrf){}
 static final Set<String> INPUT=Set.of("operationId","groupId","businessId","purpose","name","mediaType","size","sha256");
 static String permission(String purpose){return switch(purpose){case "FINANCE_COLLECTION"->"finance.money.collect";case "FINANCE_REFUND"->"finance.money.refund";case "FINANCE_CORRECTION"->"finance.money.reverse";default->throw Tickets.bad();};}
 static String group(long tenant,long company,String ticket){return UUID.nameUUIDFromBytes(("finance:"+tenant+":"+company+":"+ticket).getBytes(StandardCharsets.UTF_8)).toString();}
 Actor authorize(String ticket,String purpose,String token,String csrf,boolean write,HttpServletRequest r){return authorize(ticket,purpose,token,csrf,write,true,r);}
 Actor authorize(String ticket,String purpose,String token,String csrf,boolean write,boolean purposeCapability,HttpServletRequest r){
  permission(purpose);var f=identity.read(token,csrf,write,purpose,r);
  if(!Boolean.TRUE.equals(f.get("enabled"))||!"EMPLOYEE".equals(f.get("identityType"))||!Boolean.TRUE.equals(f.get("departmentEnabled")))throw new Problem(403,"ACCESS_DENIED");
  var permissions=(List<?>)f.getOrDefault("permissions",List.of());if(!permissions.contains("finance.money.read")||purposeCapability&&!permissions.contains(permission(purpose)))throw new Problem(403,"ACCESS_DENIED");
  long tenant=Tickets.id(f.get("tenantId")),user=Tickets.id(f.get("userId"));var rows=t.db.queryForList("SELECT r.company_id FROM ticket_record r WHERE r.id=? AND r.tenant_id=? AND EXISTS(SELECT 1 FROM ticket_create_operation o WHERE o.operation_id=r.operation_id AND o.state='COMPLETED')",Tickets.uuid(ticket),tenant);
  if(rows.size()!=1||!((List<?>)f.getOrDefault("companyIds",List.of())).contains(rows.getFirst().get("company_id").toString()))throw new Problem(404,"TARGET_NOT_ACCESSIBLE");return new Actor(tenant,user,Tickets.id(rows.getFirst().get("company_id")),token,csrf);
 }
 Actor actor(String ticket,String purpose,HttpServletRequest r,boolean write){if(r.getParameterMap().size()!=0)throw Tickets.bad();if(write)Chain.source(r);return authorize(ticket,purpose,Chain.cookie(r),r.getHeader("X-CSRF-TOKEN"),write,r);}
 static Map<String,Object> input(Map<String,Object>b){if(!b.keySet().equals(INPUT))throw Tickets.bad();var out=new TreeMap<String,Object>();for(String key:List.of("operationId","groupId","businessId"))out.put(key,Tickets.uuid(b.get(key)));String purpose=Tickets.text(b.get("purpose"),1,32,false);permission(purpose);out.put("purpose",purpose);String name=Tickets.text(b.get("name"),1,200,false);if(name.contains("/")||name.contains("\\")||name.contains(":")||name.equals(".")||name.equals(".."))throw Tickets.bad();out.put("name",name);String media=Tickets.text(b.get("mediaType"),1,64,false);if(!Set.of("application/pdf","image/png","image/jpeg").contains(media))throw new Problem(415,"UNSUPPORTED_MEDIA_TYPE");out.put("mediaType",media);if(!(b.get("size") instanceof String size)||!size.matches("[1-9][0-9]{0,7}"))throw Tickets.bad();long count=Tickets.id(size);if(count>FileStore.MAX)throw new Problem(413,"FILE_TOO_LARGE");out.put("size",size);if(!(b.get("sha256") instanceof String sha)||!sha.matches("[0-9a-f]{64}"))throw Tickets.bad();out.put("sha256",sha);return out;}
 Path path(String file,String suffix){Path p=root.resolve(Tickets.uuid(file)+suffix).normalize();if(!p.getParent().equals(root)||Files.isSymbolicLink(p))throw new Problem(503,"PRIVATE_FILE_UNAVAILABLE");return p;}
 <R> R transaction(Function<JdbcTemplate,R> work){java.sql.Connection c=null;boolean uncertain=false,started=false;try{c=Objects.requireNonNull(t.db.getDataSource()).getConnection();c.setAutoCommit(false);started=true;var db=new JdbcTemplate(new SingleConnectionDataSource(c,true));R out=work.apply(db);try{c.commit();}catch(Exception failure){uncertain=true;throw failure;}return out;}catch(Exception failure){if(c!=null&&started)try{c.rollback();}catch(Exception rollback){uncertain=true;failure.addSuppressed(rollback);}if(uncertain){if(c!=null)try{c.abort(Runnable::run);}catch(Exception abort){failure.addSuppressed(abort);}var problem=new Problem(503,"OPERATION_RESULT_UNKNOWN");problem.initCause(failure);throw problem;}if(failure instanceof Problem problem)throw problem;var problem=new Problem(503,"OPERATION_RESULT_UNKNOWN");problem.initCause(failure);throw problem;}finally{if(c!=null)try{c.close();}catch(Exception ignored){}}}
 static void audit(JdbcTemplate db,Map<String,Object>f,String action){db.update("INSERT INTO ticket_finance_voucher_audit(upload_id,action,tenant_id,actor_user_id,file_id,command_digest,occurred_at) VALUES(?,?,?,?,?,?,UTC_TIMESTAMP(3))",f.get("upload_id"),action,f.get("tenant_id"),f.get("actor_user_id"),f.get("file_id"),f.get("command_digest"));}
 Map<String,Object> own(String ticket,String upload,Actor a){var rows=t.db.queryForList("SELECT * FROM ticket_finance_voucher WHERE upload_id=? AND ticket_id=? AND tenant_id=? AND actor_user_id=?",Tickets.uuid(upload),Tickets.uuid(ticket),a.tenant,a.user);if(rows.size()!=1)throw new Problem(404,"TARGET_NOT_ACCESSIBLE");return rows.getFirst();}
 Map<String,Object> lookup(String ticket,String upload,HttpServletRequest r,boolean write){var rows=t.db.queryForList("SELECT purpose FROM ticket_finance_voucher WHERE upload_id=? AND ticket_id=?",Tickets.uuid(upload),Tickets.uuid(ticket));if(rows.size()!=1){if(write)Chain.source(r);identity.read(Chain.cookie(r),r.getHeader("X-CSRF-TOKEN"),write,null,r);throw new Problem(404,"TARGET_NOT_ACCESSIBLE");}Actor a=actor(ticket,rows.getFirst().get("purpose").toString(),r,write);return own(ticket,upload,a);}
 static Map<String,Object> dto(Map<String,Object>f){var out=new LinkedHashMap<String,Object>();for(String[]p:new String[][]{{"uploadId","upload_id"},{"fileId","file_id"},{"ticketId","ticket_id"},{"groupId","group_id"},{"businessId","business_id"},{"purpose","purpose"},{"name","name"},{"mediaType","media_type"},{"sha256","sha256"},{"state","state"}})out.put(p[0],f.get(p[1]));out.put("size",f.get("size_bytes").toString());out.put("nextAction","READY".equals(f.get("state"))?"NONE":"EXPLICIT_RETRY_SAME_FILE");return out;}
 @PostMapping("/api/ticket/tickets/{ticket}/finance-vouchers") public Map<String,Object> register(@PathVariable String ticket,@RequestBody Map<String,Object>b,HttpServletRequest r){var in=input(b);String op=in.get("operationId").toString();if(!op.equals(Tickets.uuid(Chain.single(r,"Idempotency-Key"))))throw Tickets.bad();var a=actor(ticket,in.get("purpose").toString(),r,true);if(!group(a.tenant,a.company,ticket).equals(in.get("groupId")))throw new Problem(404,"TARGET_NOT_ACCESSIBLE");String digest=Tickets.hash(in);return dto(transaction(db->{db.update("INSERT INTO ticket_actor_lock(tenant_id,user_id) VALUES(?,?) ON DUPLICATE KEY UPDATE user_id=ticket_actor_lock.user_id",a.tenant,a.user);db.queryForMap("SELECT * FROM ticket_actor_lock WHERE tenant_id=? AND user_id=? FOR UPDATE",a.tenant,a.user);var old=db.queryForList("SELECT * FROM ticket_finance_voucher WHERE upload_id=? FOR UPDATE",op);if(!old.isEmpty()){var f=old.getFirst();if(Tickets.id(f.get("tenant_id"))!=a.tenant||Tickets.id(f.get("actor_user_id"))!=a.user||!ticket.equals(f.get("ticket_id")))throw new Problem(404,"TARGET_NOT_ACCESSIBLE");if(!digest.equals(f.get("command_digest")))throw new Problem(409,"IDEMPOTENCY_CONFLICT");return f;}String file=UUID.randomUUID().toString();db.update("INSERT INTO ticket_finance_voucher(upload_id,file_id,tenant_id,actor_user_id,company_id,ticket_id,group_id,business_id,purpose,name,media_type,size_bytes,sha256,command_digest,state,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,'UPLOADING',UTC_TIMESTAMP(3),UTC_TIMESTAMP(3))",op,file,a.tenant,a.user,a.company,ticket,in.get("groupId"),in.get("businessId"),in.get("purpose"),in.get("name"),in.get("mediaType"),Long.parseLong(in.get("size").toString()),in.get("sha256"),digest);var f=db.queryForMap("SELECT * FROM ticket_finance_voucher WHERE upload_id=?",op);audit(db,f,"REGISTERED");return f;}));}
 @GetMapping("/api/ticket/tickets/{ticket}/finance-vouchers/{upload}") public Map<String,Object> query(@PathVariable String ticket,@PathVariable String upload,HttpServletRequest r){return dto(lookup(ticket,upload,r,false));}
 @PutMapping("/api/ticket/tickets/{ticket}/finance-vouchers/{upload}/content") public Map<String,Object> upload(@PathVariable String ticket,@PathVariable String upload,HttpServletRequest r)throws Exception{
  if(!Tickets.uuid(upload).equals(Tickets.uuid(Chain.single(r,"Idempotency-Key"))))throw Tickets.bad();var original=lookup(ticket,upload,r,true);if(!original.get("media_type").equals(Chain.single(r,"Content-Type")))throw new Problem(415,"UNSUPPORTED_MEDIA_TYPE");long expected=((Number)original.get("size_bytes")).longValue();if(r.getContentLengthLong()!=-1&&r.getContentLengthLong()!=expected)throw Tickets.bad();Path stage=path(original.get("file_id").toString(),".finance-"+UUID.randomUUID()+".part");try{var sha=MessageDigest.getInstance("SHA-256");long count=0,deadline=System.nanoTime()+120_000_000_000L;try(var in=r.getInputStream();var out=new DigestOutputStream(Files.newOutputStream(stage,StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE),sha)){byte[] buf=new byte[32768];for(int n;(n=in.read(buf))!=-1;){count+=n;if(count>expected||count>FileStore.MAX)throw new Problem(413,"FILE_TOO_LARGE");if(System.nanoTime()>deadline)throw new Problem(503,"OPERATION_RESULT_UNKNOWN");out.write(buf,0,n);}}if(count!=expected||!HexFormat.of().formatHex(sha.digest()).equals(original.get("sha256")))throw new Problem(409,"FILE_CONTENT_MISMATCH");if(!media(stage).equals(original.get("media_type")))throw new Problem(415,"UNSUPPORTED_MEDIA_TYPE");try(var ch=FileChannel.open(stage,StandardOpenOption.WRITE)){ch.force(true);}FileStore.reset(r);lookup(ticket,upload,r,true);return dto(transaction(db->{var f=db.queryForMap("SELECT * FROM ticket_finance_voucher WHERE upload_id=? FOR UPDATE",upload);if(!f.get("command_digest").equals(original.get("command_digest")))throw new Problem(409,"IDEMPOTENCY_CONFLICT");Path bin=path(f.get("file_id").toString(),".bin");try{if("READY".equals(f.get("state"))){verify(bin,f);return f;}if(Files.exists(bin,LinkOption.NOFOLLOW_LINKS))verify(bin,f);else Files.move(stage,bin,StandardCopyOption.ATOMIC_MOVE);db.update("UPDATE ticket_finance_voucher SET state='READY',updated_at=UTC_TIMESTAMP(3) WHERE upload_id=? AND state='UPLOADING'",upload);audit(db,f,"READY");return db.queryForMap("SELECT * FROM ticket_finance_voucher WHERE upload_id=?",upload);}catch(IOException e){throw new Problem(503,"OPERATION_RESULT_UNKNOWN");}}));}finally{try{Files.deleteIfExists(stage);}catch(IOException ignored){}}}
 static void verify(Path bin,Map<String,Object>f)throws IOException{if(!Files.isRegularFile(bin,LinkOption.NOFOLLOW_LINKS)||Files.size(bin)!=((Number)f.get("size_bytes")).longValue())throw new IOException("Private evidence unavailable");try(var in=Files.newInputStream(bin)){var sha=MessageDigest.getInstance("SHA-256");byte[]buf=new byte[32768];for(int n;(n=in.read(buf))!=-1;)sha.update(buf,0,n);if(!HexFormat.of().formatHex(sha.digest()).equals(f.get("sha256")))throw new IOException("Private evidence unavailable");}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 String media(Path file)throws IOException{byte[] prefix;try(var in=Files.newInputStream(file)){prefix=in.readNBytes(8);}if(prefix.length>=5&&new String(prefix,0,5,StandardCharsets.US_ASCII).equals("%PDF-")){try(var doc=org.apache.pdfbox.Loader.loadPDF(file.toFile(),()->new org.apache.pdfbox.io.ScratchFile(org.apache.pdfbox.io.MemoryUsageSetting.setupTempFileOnly().setTempDir(root.toFile())))){if(doc.isEncrypted()||doc.getNumberOfPages()<1||doc.getNumberOfPages()>1000)throw new IOException();return "application/pdf";}catch(Exception e){throw new Problem(415,"UNSUPPORTED_MEDIA_TYPE");}}boolean png=Arrays.equals(prefix,new byte[]{(byte)137,80,78,71,13,10,26,10}),jpg=prefix.length>=3&&prefix[0]==(byte)255&&prefix[1]==(byte)216&&prefix[2]==(byte)255;if(!png&&!jpg)throw new Problem(415,"UNSUPPORTED_MEDIA_TYPE");try(var input=javax.imageio.ImageIO.createImageInputStream(file.toFile())){var readers=javax.imageio.ImageIO.getImageReaders(input);if(!readers.hasNext())throw new IOException();var reader=readers.next();try{reader.setInput(input,true,true);if((long)reader.getWidth(0)*reader.getHeight(0)>16_000_000L||reader.read(0)==null)throw new IOException();}finally{reader.dispose();}}catch(Exception e){throw new Problem(415,"UNSUPPORTED_MEDIA_TYPE");}return png?"image/png":"image/jpeg";}
 @GetMapping("/api/ticket/tickets/{ticket}/finance-vouchers/{upload}/content") public void download(@PathVariable String ticket,@PathVariable String upload,HttpServletRequest r,HttpServletResponse response)throws IOException{var f=lookup(ticket,upload,r,false);if(!"READY".equals(f.get("state")))throw new Problem(409,"VOUCHER_NOT_READY");stream(f,r,response);}
 @RequestMapping(value="/api/ticket/tickets/{ticket}/finance-voucher-files/{file}/content",method={RequestMethod.GET,RequestMethod.HEAD}) public void stableDownload(@PathVariable String ticket,@PathVariable String file,HttpServletRequest r,HttpServletResponse response)throws IOException{if(!r.getParameterMap().isEmpty())throw Tickets.bad();var rows=t.db.queryForList("SELECT * FROM ticket_finance_voucher WHERE file_id=? AND ticket_id=? AND state='READY'",Tickets.uuid(file),Tickets.uuid(ticket));if(rows.size()!=1){identity.read(Chain.cookie(r),null,false,null,r);throw new Problem(404,"TARGET_NOT_ACCESSIBLE");}var f=rows.getFirst();var a=authorize(ticket,f.get("purpose").toString(),Chain.cookie(r),null,false,false,r);if(Tickets.id(f.get("tenant_id"))!=a.tenant||Tickets.id(f.get("company_id"))!=a.company||!group(a.tenant,a.company,ticket).equals(f.get("group_id")))throw new Problem(404,"TARGET_NOT_ACCESSIBLE");stream(f,r,response);}
 void stream(Map<String,Object>f,HttpServletRequest r,HttpServletResponse response)throws IOException{Path bin=path(f.get("file_id").toString(),".bin");verify(bin,f);long size=((Number)f.get("size_bytes")).longValue();long[]range=range(Collections.list(r.getHeaders("Range")),size);long start=range[0],end=range[1];if(!Collections.list(r.getHeaders("Range")).isEmpty()){response.setStatus(206);response.setHeader("Content-Range","bytes "+start+"-"+end+"/"+size);}response.setHeader("Cache-Control","no-store");response.setHeader("X-Content-Type-Options","nosniff");response.setHeader("Accept-Ranges","bytes");response.setContentType(f.get("media_type").toString());response.setContentLengthLong(end-start+1);response.setHeader("Content-Disposition","attachment; filename=\"evidence\"; filename*=UTF-8''"+java.net.URLEncoder.encode(f.get("name").toString(),StandardCharsets.UTF_8).replace("+","%20"));if("HEAD".equals(r.getMethod()))return;try(var channel=FileChannel.open(bin,StandardOpenOption.READ)){channel.position(start);var in=Channels.newInputStream(channel);long left=end-start+1;byte[]buf=new byte[32768];while(left>0){int n=in.read(buf,0,(int)Math.min(left,buf.length));if(n<0)throw new IOException("Incomplete private evidence");response.getOutputStream().write(buf,0,n);left-=n;}}}
 static long[] range(List<String> headers,long size){long start=0,end=size-1;if(headers.isEmpty())return new long[]{start,end};try{if(headers.size()!=1)throw new Exception();var m=Pattern.compile("bytes=([0-9]*)-([0-9]*)").matcher(headers.getFirst());if(!m.matches()||m.group(1).isEmpty()&&m.group(2).isEmpty())throw new Exception();if(m.group(1).isEmpty()){long suffix=Long.parseLong(m.group(2));if(suffix<1)throw new Exception();start=Math.max(0,size-suffix);}else{start=Long.parseLong(m.group(1));if(!m.group(2).isEmpty())end=Math.min(end,Long.parseLong(m.group(2)));}if(start>=size||start>end)throw new Exception();return new long[]{start,end};}catch(Exception e){throw new Problem(416,"RANGE_NOT_SATISFIABLE");}}
 @PostMapping("/internal/ticket/finance-voucher-fact") public Map<String,Object> fact(@RequestBody Map<String,Object>b,HttpServletRequest r){ApprovalBoundaryController.trusted(r,Set.of("finance-ticket"));return factRead(b,r);}
 Map<String,Object> factRead(Map<String,Object>b,HttpServletRequest r){if(!b.keySet().equals(Set.of("sessionToken","ticketId","groupId","companyId","businessId","fileId","purpose","evidenceDigest"))||!(b.get("sessionToken") instanceof String token)||token.isBlank())throw Tickets.bad();String ticket=Tickets.uuid(b.get("ticketId")),purpose=Tickets.text(b.get("purpose"),1,32,false);var a=authorize(ticket,purpose,token,null,false,r);if(!Long.toString(a.company).equals(b.get("companyId"))||!group(a.tenant,a.company,ticket).equals(b.get("groupId")))throw new Problem(404,"TARGET_NOT_ACCESSIBLE");Tickets.uuid(b.get("businessId"));Tickets.uuid(b.get("fileId"));if(!(b.get("evidenceDigest") instanceof String digest)||!digest.matches("[0-9a-f]{64}"))throw Tickets.bad();var rows=t.db.queryForList("SELECT * FROM ticket_finance_voucher WHERE file_id=? AND tenant_id=? AND company_id=? AND ticket_id=? AND group_id=? AND business_id=? AND purpose=? AND sha256=? AND state='READY'",b.get("fileId"),a.tenant,a.company,ticket,b.get("groupId"),b.get("businessId"),purpose,digest);if(rows.size()!=1)throw new Problem(404,"VOUCHER_FACT_NOT_FOUND");var f=rows.getFirst();try{verify(path(f.get("file_id").toString(),".bin"),f);}catch(IOException unavailable){throw new Problem(503,"PRIVATE_FILE_UNAVAILABLE");}var out=new LinkedHashMap<String,Object>();out.put("tenantId",Long.toString(a.tenant));out.put("actorUserId",Long.toString(a.user));for(String key:List.of("companyId","ticketId","groupId","businessId","fileId","purpose"))out.put(key,b.get(key));out.put("sha256",digest);out.put("size",f.get("size_bytes").toString());out.put("state","AVAILABLE");out.put("checkedAt",Instant.now().toString());return out;}
 @ModelAttribute public void noStore(HttpServletResponse r){r.setHeader("Cache-Control","no-store");}
 @ExceptionHandler(Problem.class) public org.springframework.http.ResponseEntity<Map<String,Object>> problem(Problem p){return org.springframework.http.ResponseEntity.status(p.status).header("Cache-Control","no-store").body(Map.of("code",p.code,"retryable",p.status==503));}
 @ExceptionHandler(Exception.class) public org.springframework.http.ResponseEntity<Map<String,Object>> failure(Exception e){return problem(new Problem(503,"OPERATION_RESULT_UNKNOWN"));}
}




